b9cbf92ed85/p:3/label:Área de plano :/box:[70.464,189.98,122.872,197.66]"},"REGISTRY_AREA":{"page":3,"label":"Área de registro :","sourceItems":[{"text":"Área de registro :","box":[65.904,203.66,125.032,211.34]},{"text":"164,08","box":[160.7,203.18,186.345,211.58]},{"text":"m²","box":[221.09,203.66,230.248,211.34]}],"originalText":"Área de registro : 164,08 m²","raw":"164,08 m²","originalValue":"164,08","originalUnit":"m²","normalizedM2":"164.08","validation":"VALID","box":[65.904,203.18,230.248,211.58],"selector":"pdf:5d5fe85911129180c157f7083060edf95724cf373babfbb9bf350b9cbf92ed85/p:3/label:Área de registro :/box:[65.904,203.66,125.032,211.34]"},"CONSTRUCTION_TOTAL":{"page":5,"label":"Total Construcción","sourceItems":[{"text":"Total Construcción","box":[27.24,283.01,75.054,288.77]},{"text":"136,00","box":[95.064,281.57,116.938,288.77]},{"text":"m²","box":[120.02,281.57,128.297,288.77]}],"originalText":"Total Construcción 136,00 m²","raw":"136,00 m²","originalValue":"136,00","originalUnit":"m²","normalizedM2":"136.00","validation":"VALID","box":[27.24,281.57,128.297,288.77],"selector":"pdf:5d5fe85911129180c157f7083060edf95724cf373babfbb9bf350b9cbf92ed85/p:5/label:Total Construcción/box:[27.24,283.01,75.054,288.77]"}}}}'::jsonb;
  BEGIN proof:=ob.raw_text::jsonb;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'reviewed factual PDF evidence required' USING ERRCODE='23514';END;
  a:=proof->'association';actor:=twuanis_remates_private.live_session_actor();
  IF public.is_current_user_owner() IS DISTINCT FROM true OR cv.actor_id<>actor OR cv.snapshot->'reviewed' IS DISTINCT FROM 'true'::jsonb
   OR NOT twuanis_remates_private.independent_source_allowed(cv.source_id)
   OR jsonb_typeof(proof) IS DISTINCT FROM 'object' OR proof->>'format' IS DISTINCT FROM 'bp-reviewed-factual-areas-v1' OR proof->>'sourceUse' IS DISTINCT FROM 'SOURCE-USE UNRESOLVED'
   OR proof->'ownerReview'->>'decision' IS DISTINCT FROM 'OWNER_FACTUAL_MEASUREMENTS' OR proof->'ownerReview'->>'scope' IS DISTINCT FROM 'PHASE_4_1D_STEP_4'
   OR proof->'ownerReview'->>'legalFinding' IS DISTINCT FROM 'UNRESOLVED' OR proof->'ownerReview'->>'bankPermission' IS DISTINCT FROM 'NOT_ASSERTED'
   OR proof->'ownerReview'->>'restrictionAssessment' IS DISTINCT FROM 'AMBIGUOUS' OR jsonb_array_length(coalesce(proof->'restrictions','[]'::jsonb))=0
   OR a->>'propertyId' IS DISTINCT FROM NEW.property_id::text OR ob.record_key IS DISTINCT FROM 'codBien:'||(a->>'codBien')
   OR ob.source_id IS DISTINCT FROM cv.source_id OR ob.source_url IS DISTINCT FROM a->>'documentUrl'
   OR NOT EXISTS(SELECT 1 FROM twuanis_remates_private.listings l JOIN twuanis_remates_private.offering_properties op ON op.offering_id=l.offering_id WHERE l.id::text=a->>'listingId' AND op.property_id=NEW.property_id)
   OR approved->(a->>'codBien')->>'sha256' IS DISTINCT FROM a->>'documentSHA256' OR (a-ARRAY['listingId','propertyId']) IS DISTINCT FROM approved->(a->>'codBien')->'sourceAssociation'
   OR NEW.dimension NOT IN('property_area','construction_area') OR NEW.kind<>'exact' OR NEW.exact_value IS NULL OR NEW.exact_value<=0
  THEN RAISE EXCEPTION 'explicit scoped Owner factual area review required' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(proof->'measurements') IS DISTINCT FROM 'array' OR jsonb_array_length(proof->'measurements') IS DISTINCT FROM 3 OR proof->'selection' IS DISTINCT FROM '{"property_area":"PLAN_AREA","construction_area":"CONSTRUCTION_TOTAL","registry":"PRESERVED_SEPARATELY"}'::jsonb THEN RAISE EXCEPTION 'explicit plan/total measurement selection required' USING ERRCODE='23514';END IF;
  FOR k IN SELECT unnest(ARRAY['PLAN_AREA','REGISTRY_AREA','CONSTRUCTION_TOTAL']) LOOP
   IF (SELECT count(*) FROM jsonb_array_elements(proof->'measurements') m WHERE m->>'identity'=k)<>1 THEN RAISE EXCEPTION 'distinct factual measurement identities required' USING ERRCODE='23514';END IF;
   SELECT m INTO measurement FROM jsonb_array_elements(proof->'measurements')m WHERE m->>'identity'=k;
   IF measurement->'candidate' IS DISTINCT FROM approved->(a->>'codBien')->'candidates'->k OR measurement->>'normalizedM2' IS DISTINCT FROM approved->(a->>'codBien')->>k OR measurement->'candidate'->>'normalizedM2' IS DISTINCT FROM measurement->>'normalizedM2'
    OR measurement->'candidate'->>'originalUnit' NOT IN('m²','m2') OR measurement->'candidate'->>'raw' !~ '^([0-9]{1,3}([.][0-9]{3})+|[0-9]+)(,[0-9]{1,18})? *m(²|2)$'
    OR replace(replace(regexp_replace(measurement->'candidate'->>'raw',' *m(²|2)$','','i'),'.',''),',','.')::numeric IS DISTINCT FROM (measurement->>'normalizedM2')::numeric
    OR (measurement->'candidate'->>'page')::int NOT BETWEEN 1 AND 16
    OR measurement->'candidate'->>'selector' NOT LIKE 'pdf:'||(a->>'documentSHA256')||'/p:'||(measurement->'candidate'->>'page')||'/label:%'
    OR measurement->'candidate'->>'label' IS DISTINCT FROM (CASE k WHEN 'PLAN_AREA' THEN 'Área de plano :' WHEN 'REGISTRY_AREA' THEN 'Área de registro :' ELSE 'Total Construcción' END)
   THEN RAISE EXCEPTION 'verified original factual PDF measurement required' USING ERRCODE='23514';END IF;
  END LOOP;
  k:=CASE NEW.dimension WHEN 'property_area' THEN 'PLAN_AREA' ELSE 'CONSTRUCTION_TOTAL' END;
  SELECT m INTO measurement FROM jsonb_array_elements(proof->'measurements')m WHERE m->>'identity'=k;
  IF NEW.field_path IS DISTINCT FROM 'pdf.normalized_'||lower(k) OR NEW.ordinal<>0 OR NEW.exact_value IS DISTINCT FROM (measurement->>'normalizedM2')::numeric
   OR NOT EXISTS(SELECT 1 FROM twuanis_remates_private.observation_fields f WHERE f.observation_id=ob.id AND f.field_path=NEW.field_path AND f.ordinal=0 AND f.unit='m2' AND f.validation='VALID' AND f.raw_value=measurement->>'normalizedM2' AND f.document_page=(measurement->'candidate'->>'page')::int AND f.selector=measurement->'candidate'->>'selector')
  THEN RAISE EXCEPTION 'area normalization/source identity mismatch' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;
 IF NEW.dimension NOT IN('property_area','construction_area') THEN RETURN NEW;END IF;
 IF NEW.kind<>'exact' OR NEW.exact_value IS NULL OR NEW.exact_value<=0 OR NEW.field_path IS DISTINCT FROM 'csv.normalized_'||NEW.dimension THEN RAISE EXCEPTION 'explicit Banco Popular exact area evidence required' USING ERRCODE='23514';END IF;
 SELECT f.raw_value INTO raw FROM twuanis_remates_private.observation_fields f WHERE f.observation_id=NEW.evidence_id AND f.field_path='csv.raw_'||NEW.dimension AND f.ordinal=NEW.ordinal;
 IF raw IS NULL OR btrim(raw)!~* '^([0-9]{1,3}([.][0-9]{3})+|[0-9]+)(,[0-9]{1,18})? *m(²|2)$' THEN RAISE EXCEPTION 'unambiguous original Banco Popular area required' USING ERRCODE='23514';END IF;
 amount:=replace(replace(regexp_replace(btrim(raw),' *m(²|2)$','','i'),'.',''),',','.')::numeric;
 SELECT f.raw_value INTO normalized FROM twuanis_remates_private.observation_fields f WHERE f.observation_id=NEW.evidence_id AND f.field_path=NEW.field_path AND f.ordinal=NEW.ordinal AND f.unit='m2' AND f.validation='VALID';
 IF amount<=0 OR normalized IS NULL OR normalized!~ '^[0-9]+([.][0-9]+)?$' OR normalized::numeric<>amount OR NEW.exact_value<>amount THEN RAISE EXCEPTION 'area normalization/source identity mismatch' USING ERRCODE='23514';END IF;
 RETURN NEW;
END$function$;
COMMIT;
